begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('dddddddd-0000-4000-8000-000000000001','gauge-a@example.test'),('dddddddd-0000-4000-8000-000000000002','gauge-b@example.test');
select ok(not has_function_privilege('anon','public.apply_project_gauge_command(uuid,uuid,bigint,jsonb)','EXECUTE'),'anonymous mutation denied');
select ok(not has_function_privilege('anon','public.get_project_gauges(uuid)','EXECUTE'),'anonymous read denied');
select ok(not has_table_privilege('authenticated','public.project_gauges','INSERT'),'direct insert denied');
select ok(not has_table_privilege('authenticated','public.project_gauges','UPDATE'),'direct update denied');
select ok(not has_table_privilege('authenticated','public.project_gauges','DELETE'),'direct delete denied');
select ok(not has_table_privilege('authenticated','public.project_gauge_commands','SELECT'),'receipts inaccessible');
set local role authenticated;
set local request.jwt.claim.sub='dddddddd-0000-4000-8000-000000000001';
select set_config('test.gp',(public.create_project(gen_random_uuid(),'게이지 프로젝트',null)->>'id'),true);
select set_config('test.ga','{"type":"save","id":"dddddddd-1000-4000-8000-000000000001","data":{"kind":"pattern","stitches":22,"rows":30,"width":10,"height":10,"unit":"cm","technique":"메리야스"}}',true);
select is(public.get_project_gauges(current_setting('test.gp')::uuid)->'items','[]'::jsonb,'optional empty gauge collection');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,'dddddddd-2000-4000-8000-000000000001',0,current_setting('test.ga')::jsonb)->>'status','applied','create pattern');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,'dddddddd-2000-4000-8000-000000000001',0,current_setting('test.ga')::jsonb)->>'status','duplicate','retry same request returns receipt');
select throws_ok(format('select public.apply_project_gauge_command(%L,%L,0,%L)',current_setting('test.gp'),'dddddddd-2000-4000-8000-000000000001',jsonb_set(current_setting('test.ga')::jsonb,'{data,stitches}','24')),'22023',null,'same ID with changed content denied');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),0,current_setting('test.ga')::jsonb)->>'status','conflict','stale revision rejected');
select is((select count(*) from public.project_gauges),1::bigint,'duplicate and conflict do not create extra record');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),1,jsonb_set(current_setting('test.ga')::jsonb,'{data,stitches}','24'))->>'status','applied','edit pattern');
select is((select stitches from public.project_gauges),24,'edited stitches persisted');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),2,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.ga')::jsonb,'{id}','"dddddddd-1000-4000-8000-000000000002"')),'23505',null,'only one pattern allowed');
select set_config('test.gs','{"type":"save","id":"dddddddd-1000-4000-8000-000000000003","data":{"kind":"sample","name":"後블로킹","stitches":20,"rows":28,"width":4,"height":4,"unit":"inch","needle_size_mm":3.75,"needle_label":"US 5","blocking":"after","measured_on":"2026-10-20","yarn":"울","notes":"기록"}}',true);
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),2,current_setting('test.gs')::jsonb)->>'status','applied','sample inch after blocking saved');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),3,jsonb_set(jsonb_set(jsonb_set(current_setting('test.gs')::jsonb,'{id}','"dddddddd-1000-4000-8000-000000000004"'),'{data,blocking}','"before"'),'{data,measured_on}','"2026-10-19"'))->>'status','applied','multiple sample before blocking saved');
select is(public.get_project_gauges(current_setting('test.gp')::uuid)->'items'->0->>'measured_on','2026-10-20','most recently measured sample first');
select is((select unit from public.project_gauges where id='dddddddd-1000-4000-8000-000000000003'),'inch','unit stored without conversion');
select is((select needle_size_mm from public.project_gauges where id='dddddddd-1000-4000-8000-000000000003'),3.75::numeric,'structured needle size preserved');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,width}','0')),'23514',null,'zero dimensions rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,rows}','-1')),'23514',null,'negative counts rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,height}','0.0001')),'23514',null,'excess decimal precision rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,unit}','"mm"')),'23514',null,'unsupported unit rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,needle_size_mm}','-1')),'23514',null,'invalid needle rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,name}','""')),'23514',null,'blank sample name rejected');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),jsonb_set(current_setting('test.gs')::jsonb,'{data,measured_on}','"2026-02-30"')),'22008',null,'invalid calendar date rejected');
select is(public.get_project_gauges(current_setting('test.gp')::uuid)->>'revision','4','failed writes leave revision unchanged');
select is((select revision from public.projects where id=current_setting('test.gp')::uuid),0::bigint,'gauge writes do not change project metadata revision');
select set_config('test.gsnapshot',(select jsonb_agg(to_jsonb(g) order by id)::text from public.project_gauges g),true);
select set_config('test.gwork',(public.get_project_detail(current_setting('test.gp')::uuid)->'parts'->0->>'workItemId'),true);
select is((select revision from public.work_items where id=current_setting('test.gwork')::uuid),0::bigint,'counter revision unchanged');
select is(public.update_project(current_setting('test.gp')::uuid,0,'변경된 이름',null,'active')->>'result','updated','project metadata still editable');
select is((select jsonb_agg(to_jsonb(g) order by id) from public.project_gauges g),current_setting('test.gsnapshot')::jsonb,'metadata edit preserves gauges');
select is(public.apply_counter_command(gen_random_uuid(),current_setting('test.gwork')::uuid,0,'2026-10-20T03:00:00Z','gauge-test','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','counter still works with gauge records');
select is((select jsonb_agg(to_jsonb(g) order by id) from public.project_gauges g),current_setting('test.gsnapshot')::jsonb,'counting preserves gauge records');
set local request.jwt.claim.sub='dddddddd-0000-4000-8000-000000000002';
select is((select count(*) from public.project_gauges),0::bigint,'RLS hides another owner gauges');
select throws_ok(format('select public.get_project_gauges(%L)',current_setting('test.gp')),'P0002',null,'other owner RPC read denied');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),current_setting('test.gs')),'P0002',null,'other owner RPC mutation denied');
set local request.jwt.claim.sub='dddddddd-0000-4000-8000-000000000001';
select is(public.delete_project(current_setting('test.gp')::uuid,1)->>'result','deleted','project deleted');
select is((select count(*) from public.project_gauges),0::bigint,'deleted project gauges hidden');
select throws_ok(format('select public.apply_project_gauge_command(%L,gen_random_uuid(),4,%L)',current_setting('test.gp'),current_setting('test.gs')),'P0002',null,'deleted project mutation denied');
select is(public.restore_project(current_setting('test.gp')::uuid,gen_random_uuid(),2)->>'status','restored','project restored');
select is((select jsonb_agg(to_jsonb(g) order by id) from public.project_gauges g),current_setting('test.gsnapshot')::jsonb,'delete and restore fully preserve gauge IDs values and timestamps');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),4,jsonb_set(current_setting('test.gs')::jsonb,'{data,notes}','"수정 메모"'))->>'status','applied','sample can be edited after recovery');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,'dddddddd-2000-4000-8000-000000000002',5,'{"type":"delete","id":"dddddddd-1000-4000-8000-000000000003"}')->>'status','applied','sample soft deleted');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,'dddddddd-2000-4000-8000-000000000002',5,'{"type":"delete","id":"dddddddd-1000-4000-8000-000000000003"}')->>'status','duplicate','delete is idempotent');
select is((select count(*) from public.project_gauges where kind='sample'),1::bigint,'deleted sample omitted');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),6,'{"type":"delete","id":"dddddddd-1000-4000-8000-000000000001"}')->>'status','applied','pattern soft deleted');
select is(public.apply_project_gauge_command(current_setting('test.gp')::uuid,gen_random_uuid(),7,jsonb_set(current_setting('test.ga')::jsonb,'{id}','"dddddddd-1000-4000-8000-000000000005"'))->>'status','applied','new pattern may be recorded after deletion');
reset role;
select is((select count(*) from public.project_gauges where deleted_at is not null and project_id=current_setting('test.gp')::uuid),2::bigint,'deleted records physically retained');
select throws_ok(format('insert into public.project_gauges(id,project_id,user_id,kind,name,stitches,rows,width,height,unit) values(gen_random_uuid(),%L,%L,''sample'',''소유권'',1,1,1,1,''cm'')',current_setting('test.gp'),'dddddddd-0000-4000-8000-000000000002'),'23503',null,'composite owner FK rejects mismatched ownership');
select * from finish();
rollback;
